package com.tekwatt.audit.dto;import com.tekwatt.audit.entity.*;import java.time.Instant;import java.util.UUID;public record AuditEventResponse(UUID id,UUID tenantId,String actorType,String actorId,String action,String resourceType,String resourceId,AuditOutcome outcome,String ipAddress,String userAgent,String correlationId,String sourceService,String details,Instant occurredAt,Instant recordedAt){public static AuditEventResponse from(AuditEvent e){return new AuditEventResponse(e.getId(),e.getTenantId(),e.getActorType(),e.getActorId(),e.getAction(),e.getResourceType(),e.getResourceId(),e.getOutcome(),e.getIpAddress(),e.getUserAgent(),e.getCorrelationId(),e.getSourceService(),e.getDetails(),e.getOccurredAt(),e.getRecordedAt());}}
